import gettext,json,pathlib,hashlib,os
p=pathlib.Path('/usr/share/locale/fr/LC_MESSAGES/emulationstation2.mo')
with p.open('rb') as f:t=gettext.GNUTranslations(f)
messages=json.loads('{"THE CLOUD FOLDER WAS NOT CHANGED.": "LE DOSSIER CLOUD N\\u2019A PAS CHANG\\u00c9.", "WAIT FOR THE CURRENT CLOUD TASK TO FINISH, THEN TRY AGAIN.": "ATTENDEZ LA FIN DE L\\u2019OP\\u00c9RATION CLOUD EN COURS, PUIS R\\u00c9ESSAYEZ.", "THE FOLDER CHECK TOOK TOO LONG. CHECK YOUR CONNECTION, THEN TRY AGAIN.": "LA V\\u00c9RIFICATION DU DOSSIER A PRIS TROP DE TEMPS. V\\u00c9RIFIEZ LA CONNEXION, PUIS R\\u00c9ESSAYEZ.", "CHOOSE A FOLDER INSIDE YOUR CLOUD STORAGE.": "CHOISISSEZ UN DOSSIER DANS VOTRE STOCKAGE CLOUD.", "THIS FOLDER NAME CAN\'T BE USED. CHOOSE A DIFFERENT FOLDER NAME.": "CE NOM DE DOSSIER NE PEUT PAS \\u00caTRE UTILIS\\u00c9. CHOISISSEZ UN AUTRE NOM.", "DON\'T USE DOUBLE QUOTES, $, `, \\\\, OR LINE BREAKS IN THE FOLDER NAME.": "N\\u2019UTILISEZ PAS DE GUILLEMETS DOUBLES, $, `, \\\\, NI DE SAUTS DE LIGNE DANS LE NOM DU DOSSIER.", "USE ONE SLASH BETWEEN FOLDERS. DON\'T USE \'.\' OR \'..\' AS FOLDER NAMES.": "UTILISEZ UNE SEULE BARRE OBLIQUE ENTRE LES DOSSIERS. N\\u2019UTILISEZ PAS \\u00ab . \\u00bb OU \\u00ab .. \\u00bb COMME NOM DE DOSSIER.", "THE FIRST PART OF THIS PATH MUST BE A BUCKET NAME. CHECK THAT NAME AND YOUR ACCESS TO THE BUCKET.": "LA PREMI\\u00c8RE PARTIE DU CHEMIN DOIT \\u00caTRE UN NOM DE BUCKET. V\\u00c9RIFIEZ CE NOM ET VOTRE ACC\\u00c8S AU BUCKET.", "YOUR PROVIDER COULDN\'T CHECK THIS FOLDER. CHECK YOUR CONNECTION AND ACCESS TO THE FOLDER, THEN TRY AGAIN.": "LE FOURNISSEUR N\\u2019A PAS PU V\\u00c9RIFIER CE DOSSIER. V\\u00c9RIFIEZ LA CONNEXION ET VOTRE ACC\\u00c8S AU DOSSIER, PUIS R\\u00c9ESSAYEZ.", "YOUR CLOUD SETTINGS COULDN\'T BE SAVED. TRY AGAIN.": "VOS PARAM\\u00c8TRES CLOUD N\\u2019ONT PAS PU \\u00caTRE ENREGISTR\\u00c9S. R\\u00c9ESSAYEZ.", "CHECK THE PATH AND YOUR CONNECTION, THEN TRY AGAIN.": "V\\u00c9RIFIEZ LE CHEMIN ET LA CONNEXION, PUIS R\\u00c9ESSAYEZ."}')
for en,want in messages.items():assert t.gettext(en)==want,en
staged=pathlib.Path('/usr/config/locale/fr/LC_MESSAGES/emulationstation2.mo')
assert p.read_bytes()==staged.read_bytes()
print(json.dumps({'passed':True,'message_count':len(messages),'staged_runtime_equal':True,'runtime_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'runtime_resolved_path':str(p.resolve()),'boot_id':pathlib.Path('/proc/sys/kernel/random/boot_id').read_text().strip()}))
